/*
===================================================================
 N8N Code Node Snippet: Parse JSON from Markdown
===================================================================
INSTRUCTIONS:
1. Set your n8n "Code" node's "Mode" to "Run Once for All Items".
2. This code assumes the incoming item has a field named 'output'
   that contains the string with the markdown code block.
   Example input string: "
3. The node will output the parsed JSON object.

*/

// This array will hold the output items from this node.
const outputItems = [];

// Loop through each item passed to this node.
// $input.all() gets all incoming items.
for (const item of $input.all()) {
  // Get the string from the 'output' field of the incoming JSON.
  const rawString = item.json.output;

  // Check if the input string is valid.
  if (typeof rawString !== 'string') {
    // If the input isn't a string, create an error entry and skip to the next item.
    outputItems.push({
      json: {
        error: "The 'output' field is not a string.",
        originalItem: item.json
      }
    });
    continue;
  }

  // Use a regular expression to remove the markdown code block fences.
  // This removes "```json" from the beginning and "```" from the end.
  // The \s* parts handle any whitespace like newlines around the fences.
  const jsonString = rawString
    .replace(/^```json\s*/, '')
    .replace(/\s*```$/, '');

  try {
    // Parse the cleaned string into a JavaScript object.
    const parsedJson = JSON.parse(jsonString);

    // Add the successfully parsed object to our output.
    // Each object pushed here will become a separate output item from this node.
    outputItems.push({
      json: parsedJson
    });

  } catch (error) {
    // If JSON.parse fails, create an error entry with details.
    outputItems.push({
      json: {
        error: "Failed to parse the JSON string after cleaning.",
        details: error.message,
        processedString: jsonString
      }
    });
  }
}

// Return the array of processed items.
return outputItems;

// Get the single incoming item from the previous node.
const inputData = items[0].json;

// Extract the common information from the top level.
const purchaseDate = inputData.purchase_date;
const vendor = inputData.vendor;

// Get the nested object that contains the line items.
const itemizedList = inputData.items;

// Create a new array to hold our structured row items.
const newItems = [];

// Loop directly through each key (the item name) in the 'items' object.
// This is more robust than the previous method.
for (const itemName in itemizedList) {

  // Create a new, flat object for this specific item.
  const newItem = {
    json: {
      date: purchaseDate,
      vendor: vendor,
      item: itemName,
      cost: itemizedList[itemName] // Get the value (cost) for the current item name.
    }
  };

  // Add the newly created item to our results array.
  newItems.push(newItem);
}

// Return the array. n8n will split this into multiple items for the next node.
return newItems;
